steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      {
        teams: teams(filter: {name: {eq: \"Web\"}}) {
          id
          name
        }
        users: users(filter: {name: {contains: \"Maya Chen\"}}) {
          id
          name
        }
      }
    "
  }'
